    MOD = 1000000007

    def dp(n, k, weights):
        dp = [[-1] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for w in range(k + 1):
                if dp[i - 1][w] != -1:
                    dp[i][w] = dp[i - 1][w]
                    if w + weights[i - 1] <= k:
                        if dp[i][w + weights[i - 1]] == -1:
                            dp[i][w + weights[i - 1]] = dp[i - 1][w] + 1
                        else:
                            dp[i][w + weights[i - 1]] = min(dp[i][w + weights[i - 1]], dp[i - 1][w] + 1)

        min_rides = min(dp[n][w] for w in range(k + 1) if dp[n][w] != -1)
        if min_rides == -1:
            return -1, 0

        count = [[0] * (k + 1) for _ in range(n + 2)]
        for w in range(k + 1):
            if dp[n][w] == min_rides:
                count[n][w] = 1

        for i in range(n, 0, -1):
            for w in range(k + 1):
                if dp[n][w] != -1:
                    if w + weights[i - 1] <= k and dp[n][w] == dp[n - 1][w + weights[i - 1]] + 1:
